-- תמל/1062 (קריית פארק לכיש): the full model.
-- Lots: supabase/seed/tamal-1062.lots.geojson. scripts/tashrit-lots.py on both sheets of the תשריט מצב מוצע (1:1250, ITM grid fit,
--   residual 0.03 m). Sheet 2 carries a stray 6-digit number (181182) that the grid fit takes for an X label, so sheet 2 was run with
--   --grid built from its frame labels. Sheet 1 holds the north (sports, park), sheet 2 the neighbourhood; they overlap between
--   N 636,065 and 636,228. Merge: every lot from sheet 2, the rest from sheet 1; lot 600 (stadium) crosses the match line and is
--   sheet 1's piece plus sheet 2's piece south of N 636,065.5 (83,141 m2, table 5: 83,033); lot 2000 (park) is sheet 1's unlabelled
--   park polygon of 68,443 m2 (table 5: 68,361). 64 lots; all table-5 lots found, every area within 0.5% of table 5 except lots 10
--   and 12 (see below).
-- Lots 10 and 12: table 5 gives 7,591 and 10,298 m2, the תשריט 3,032 and 4,326. The תשריט is right: its residential lots add up to
--   93,793 m2 against 93,816.51 in table 3.2 (מגורים), while table 5's residential lot sizes add up to 104,235. The model uses the
--   drawn lots (full_model adds a check for each).
-- Envelopes: supabase/seed/tamal-1062.envelopes.geojson. scripts/tashrit-building-lines.py --snap 0.8 (legend 'קו-בנין' #a80000),
--   sheet 2, then sheet 1 for lots 206, 502, 600, 601, 707, 800 (--append). Run through a wrapper that drops the stray label from the
--   grid fit and turns one-point segments into zero-length lines (the script stops on them). Lots 502 and 600: the lines do not close
--   a face, so the envelope is the whole lot. Lot 501: see below.
-- Rights: supabase/seed/tamal-1062.table5.json (טבלה 5, עמ' 20-21). Table 5 gives no height in metres, so the height is
--   floors x 3.3 m (הערכה). Inline copies below: coordinates rounded to 6 decimals, lots simplified to 0.3 m, envelopes to 0.4 m,
--   table 5 trimmed to the fields full_model reads. Open spaces (2000, 300-303, 311) are passed without floors_above, so they
--   get no volume: their built rights are shade structures, kiosks and park buildings of up to 150 m2 each (סעיף 4.6), not one block.
--   Lot 501: the script took one of its two envelope faces as a tower line (15 floors); the plan has two office buildings of
--   15 floors (דברי ההסבר), so the tower face is dropped and the building is spread over both faces.
--   Paths 401 and 408 are left out of the inline lots (MultiPolygons with zero-area slivers after simplification; no rights).
-- On 19.11.2026 gis.ashdod.muni.il did not answer (connect timeout from the database), so plan_builders.full_model could not run.
--   As for 603-0477232 and 603-0590729, this file runs the same function body as a session copy with the existing buildings from
--   OpenStreetMap. The demolish layer is every OSM building inside the blue line, as full_model does with the municipal layer.
--   When the GIS answers again:
--   select plan_builders.full_model('תמל/1062', <lots>, <table5>, null, <envelopes>);  -- then the hint update at the end, then
--   select plan_builders.build_city_twin();
-- Run the whole file in one session (after tamal-1062.project.sql).


-- Existing buildings from OpenStreetMap (Overpass), because gis.ashdod.muni.il did not answer on 19.11.2026.
-- Height: building:levels x 3.3 m when tagged, else 13 m (the same symbolic 4 floors as the municipal layer).
create or replace function pg_temp.osm_buildings(p_area geometry)
returns table(g geometry, h numeric)
language plpgsql
set search_path = public, extensions
as $f$
declare
  v_box box2d := ST_Extent(p_area);
  v_res jsonb;
  v_r record;
  k int;
begin
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT', '90');
  for k in 1..6 loop  -- Overpass answers 502 when at capacity: retry with a growing wait
    select * into v_r from extensions.http_get('https://overpass-api.de/api/interpreter?data=' || extensions.urlencode(
      format('[out:json][timeout:80];way["building"](%s,%s,%s,%s);out tags geom;',
             round(ST_YMin(v_box)::numeric, 6), round(ST_XMin(v_box)::numeric, 6), round(ST_YMax(v_box)::numeric, 6), round(ST_XMax(v_box)::numeric, 6))));
    exit when v_r.status = 200;
    perform pg_sleep(5 * k);
  end loop;
  if v_r.status <> 200 then raise exception 'overpass status %', v_r.status; end if;
  v_res := v_r.content::jsonb;
  return query
    select x.g, x.h from (
      select ST_SetSRID(ST_MakeValid(ST_MakePolygon(ST_MakeLine(array(
               select ST_MakePoint((pt->>'lon')::float8, (pt->>'lat')::float8)
               from jsonb_array_elements(e->'geometry') with ordinality t(pt, ord) order by ord)))), 4326) g,
             coalesce(nullif(regexp_replace(e->'tags'->>'building:levels', '[^0-9.]', '', 'g'), '')::numeric * 3.3, 13)::numeric h
      from jsonb_array_elements(v_res->'elements') e
      where e->>'type' = 'way' and jsonb_array_length(e->'geometry') >= 4
        and e->'geometry'->0 = e->'geometry'->-1
    ) x
    where ST_GeometryType(x.g) in ('ST_Polygon', 'ST_MultiPolygon') and ST_Area(ST_Transform(x.g, 2039)) > 30;
end $f$;

-- The basic model (boundary + context within 300 m), as plan_builders.basic_model builds it, with the OSM context.
with blue as (
  select ST_Union(ST_SetSRID(ST_GeomFromGeoJSON(f->'geometry'), 4326)) g
  from plan_projects p, jsonb_array_elements(p.geojson->'features') f where p.plan_number = 'תמל/1062'
), area as (select ST_Transform(ST_Buffer(ST_Transform(g, 2039), 300), 4326) g from blue),
context as (select b.g, b.h from area, pg_temp.osm_buildings(area.g) b where ST_Intersects(b.g, area.g))
insert into plan_models (plan_number, model, source, updated_at)
select p.plan_number, jsonb_build_object(
    'plan_number', p.plan_number,
    'sources', jsonb_build_object(
      'boundary', 'גבול התוכנית: הקו הכחול מתשריט מצב מוצע (שני גיליונות), מעוגן לרשת ITM',
      'context', 'מבנים קיימים: OpenStreetMap (מפת העירייה לא הייתה זמינה). הגובה לפי מספר הקומות כשהוא מסומן, אחרת סמלי, 4 קומות'),
    'summary', jsonb_build_object('lots', 0, 'units_after', coalesce(p.units_planned, 0)),
    'ui', jsonb_build_object('summary_label', concat_ws(' · ', p.title, to_char(p.units_planned, 'FM9,999') || ' דירות בתוכנית'), 'hint', ''),
    'lots', '[]'::jsonb, 'checks', '[]'::jsonb,
    'massing', jsonb_build_object('type', 'FeatureCollection', 'features', '[]'::jsonb),
    'boundary', jsonb_build_object('type', 'FeatureCollection', 'features', (select jsonb_agg(jsonb_build_object(
        'type', 'Feature', 'properties', '{}'::jsonb, 'geometry', ST_AsGeoJSON(ST_ReducePrecision(d.geom, 0.000001))::jsonb))
        from blue, ST_Dump(blue.g) d)),
    'context', jsonb_build_object('type', 'FeatureCollection', 'features', coalesce((select jsonb_agg(jsonb_build_object(
        'type', 'Feature', 'properties', jsonb_build_object('h', round(h, 1)),
        'geometry', ST_AsGeoJSON(ST_ReducePrecision(ST_SimplifyPreserveTopology(g, 0.000003), 0.000001))::jsonb)) from context), '[]'::jsonb))),
  'basic_model (OSM context)', now()
from plan_projects p where p.plan_number = 'תמל/1062'
on conflict (plan_number) do update set model = excluded.model, source = excluded.source, updated_at = now();

-- The buildings to demolish are read from the context saved above (same OSM buildings, no second Overpass call).
create or replace function pg_temp.context_buildings(p_area geometry)
returns table(g geometry, h numeric)
language sql
set search_path = public, extensions
as $f$
  select x.g, x.h from (
    select ST_SetSRID(ST_GeomFromGeoJSON(f->'geometry'), 4326) g, (f->'properties'->>'h')::numeric h
    from plan_models m, jsonb_array_elements(m.model->'context'->'features') f
    where m.plan_number = 'תמל/1062') x
  where ST_Intersects(x.g, p_area);
$f$;

-- Session copy of plan_builders.full_model (same body, read from the catalog), with the existing buildings from the OSM context.
do $d$
declare v_src text;
begin
  select p.prosrc into v_src from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'plan_builders' and p.proname = 'full_model';
  if position('plan_builders.city_buildings(' in v_src) = 0 then raise exception 'full_model changed: no city_buildings call'; end if;
  v_src := replace(v_src, 'plan_builders.city_buildings(', 'pg_temp.context_buildings(');
  execute format('create or replace function pg_temp.full_model_osm(p_plan_number text, p_lots jsonb, p_t5 jsonb, '
    'p_source text default null, p_envelopes jsonb default null) returns jsonb language plpgsql '
    'set search_path = public, extensions as %L', v_src);
end $d$;

