update plan_models set model = jsonb_set(model, '{ui,hint}', to_jsonb('המגרשים וקווי הבניין מהתשריט, הקומות מטבלה 5. הגובה (קומות כפול 3.3 מ'') והבניין עצמו הם הערכה. האצטדיון מוצג כנפח של 5 קומות על המגרש, כי צורתו אינה בתוכנית. לחיצה על מגרש מציגה את הזכויות שלו.'::text))
where plan_number = 'תמל/1062';

-- Demolition. The plan marks buildings to demolish only in lots 10, 601, 707 and road 1001 (סימון "מבנה להריסה", table 3.1);
-- the area is "פנוי ברובו מבניה" (דברי ההסבר). On 19.11.2026 OpenStreetMap shows 15 recent buildings (~600 m2 each) on residential
-- lots 11 and 14-20 of this plan, i.e. the plan's own new buildings already under construction, and 5 small structures in the park
-- (lot 2000). Those stay as existing buildings. Kept for demolition: the buildings on lot 10 and those outside every lot (roads).
update plan_models m set model = jsonb_set(model, '{demolish,features}', coalesce((
  select jsonb_agg(f) from jsonb_array_elements(m.model->'demolish'->'features') f
  where not exists (select 1 from jsonb_array_elements(m.model->'parcels'->'features') p
                    where (p->'properties'->>'lot')::int <> 10
                      and ST_Intersects(ST_SetSRID(ST_GeomFromGeoJSON(p->'geometry'), 4326),
                                        ST_PointOnSurface(ST_SetSRID(ST_GeomFromGeoJSON(f->'geometry'), 4326))))), '[]'::jsonb))
where plan_number = 'תמל/1062';
